import { useEffect, useMemo, useState } from 'react'
import { Link, NavLink, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { AnimatePresence, motion } from 'framer-motion'
import { DndContext, type DragEndEvent, useDraggable, useDroppable } from '@dnd-kit/core'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Check, CheckCheck, ChevronDown, CircleHelp, Command, Download, ExternalLink, FolderKanban, Gauge, Github, LayoutDashboard, ListTodo, Moon, MoreHorizontal, Search, Settings, Sun, Table2, Target, Timer, WandSparkles, X } from 'lucide-react'
import { getReview, type Review, type Status, type Task, type Track, useRoadmap } from './store'

const tracks: Track[] = ['AI/ML', 'Robotics', 'Design/Web', 'Video/Social', 'Resume']
const phases = ['Foundations', 'Core builds', 'Research flagship', 'LLMs & deploy', 'Finish & resume']
const projects = ['R1 Service robot', 'R2 Warehouse robot', 'R3 Medical arm', 'R4 Humanoid RL', 'H2 Thermal CNN-Transformer', 'H4 RAG + LoRA', 'H5 Paper reproduction', 'Portfolio site']
const trackClass: Record<Track, string> = { 'AI/ML': 'violet', Robotics: 'cyan', 'Design/Web': 'pink', 'Video/Social': 'amber', Resume: 'green' }
const phaseRange = (phase: number) => phase < 5 ? [phase * 4 - 3, phase * 4] : [17, 24]
const pct = (done: number, total: number) => total ? Math.round(done / total * 100) : 0
const taskProgress = (items: Task[]) => pct(items.filter((task) => task.status === 'Done').length, items.length)
const weekProgress = (tasks: Task[], week: number) => taskProgress(tasks.filter((task) => task.week === week))
const currentWeek = (startDate: string, pausedWeeks: number) => Math.max(1, Math.min(24, Math.floor((Date.now() - new Date(`${startDate}T00:00:00`).getTime()) / 604800000) + 1 - pausedWeeks))
const prettyWeek = (week: number) => `Week ${String(week).padStart(2, '0')}`
const slugify = (value: string) => value.toLowerCase().replaceAll('&', 'and').replace(/[^a-z0-9]+/g, '-')

function App() {
  const theme = useRoadmap((state) => state.theme)
  const [searchOpen, setSearchOpen] = useState(false)
  const [search, setSearch] = useState('')
  const [toast, setToast] = useState<{ message: string; undo: () => void } | null>(null)
  const [celebration, setCelebration] = useState(false)
  const navigate = useNavigate()
  const location = useLocation()
  useEffect(() => { document.documentElement.dataset.theme = theme }, [theme])
  useEffect(() => useRoadmap.subscribe((state, previous) => {
    if (state.tasks === previous.tasks) return
    const changedIndex = state.tasks.findIndex((task, index) => task.status !== previous.tasks[index]?.status)
    const completed = state.tasks[changedIndex]
    const before = previous.tasks[changedIndex]
    if (!completed || completed.status !== 'Done' || !before) return
    const groups = [
      [`${prettyWeek(completed.week)} complete`, (task: Task) => task.week === completed.week],
      [`${completed.project} complete`, (task: Task) => task.project === completed.project],
      [`Phase ${completed.phase} complete`, (task: Task) => task.phase === completed.phase],
    ] as const
    const milestone = groups.find(([, matches]) => state.tasks.some(matches) && state.tasks.filter(matches).every((task) => task.status === 'Done') && !previous.tasks.filter(matches).every((task) => task.status === 'Done'))?.[0]
    setToast({ message: milestone ?? 'Task marked done', undo: () => useRoadmap.getState().updateTask(completed.id, { status: before.status, dateDone: before.dateDone }) })
    window.setTimeout(() => setToast(null), 5000)
    if (milestone) {
      setCelebration(true)
      window.setTimeout(() => setCelebration(false), 1900)
    }
  }), [])
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k' || event.key === '/') {
        if ((event.target as HTMLElement).tagName === 'INPUT' || (event.target as HTMLElement).tagName === 'TEXTAREA') return
        event.preventDefault(); setSearchOpen(true)
      }
      if (event.key === 'Escape') setSearchOpen(false)
      if (!['INPUT', 'TEXTAREA', 'SELECT'].includes((event.target as HTMLElement).tagName)) {
        if (event.key === 'g') window.sessionStorage.setItem('roadmap-nav-key', 'g')
        else if (window.sessionStorage.getItem('roadmap-nav-key') === 'g') {
          window.sessionStorage.removeItem('roadmap-nav-key')
          const routes: Record<string, string> = { d: '/', t: '/tracker', w: '/weeks' }
          if (routes[event.key]) navigate(routes[event.key])
        }
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [navigate])
  const results = useMemo(() => {
    const normalized = search.trim().toLowerCase()
    if (!normalized) return []
    return useRoadmap.getState().tasks.filter((task) => `${task.id} ${task.topic} ${task.project} ${task.track}`.toLowerCase().includes(normalized)).slice(0, 6)
  }, [search])
  const progress = useRoadmap((state) => taskProgress(state.tasks))
  const navGroups = [
    { label: 'Workspace', links: [{ to: '/', label: 'Overview', icon: LayoutDashboard }, { to: '/tracker', label: 'Task tracker', icon: ListTodo }, { to: '/weeks', label: 'Week planner', icon: Timer }, { to: '/projects', label: 'Projects', icon: FolderKanban }] },
    { label: 'Insights', links: [{ to: '/reviews', label: 'Weekly reviews', icon: CheckCheck }, { to: '/analytics', label: 'Analytics', icon: Activity }, { to: '/resume', label: 'Resume & links', icon: Target }] },
  ]
  return <div className="app-shell">
    <aside className="sidebar">
      <Link to="/" className="brand"><span className="brand-mark"><WandSparkles size={18} /></span><span>ROUTE<span className="brand-muted">/24</span></span></Link>
      <div className="plan-label"><span className="live-dot" /> YOUR 24-WEEK PLAN</div>
      {navGroups.map((group) => <div className="nav-group" key={group.label}><p>{group.label}</p>{group.links.map(({ to, label, icon: Icon }) => <NavLink end={to === '/'} to={to} key={to} className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`}><Icon size={17} /><span>{label}</span></NavLink>)}</div>)}
      <div className="side-spacer" />
      <Link className="settings-link" to="/settings"><Settings size={17} /> Settings</Link>
      <div className="side-progress"><div className="side-progress-heading"><span>Plan progress</span><b>{progress}%</b></div><div className="progress-track"><i style={{ width: `${progress}%` }} /></div><small>{useRoadmap.getState().tasks.filter((task) => task.status === 'Done').length} of {useRoadmap.getState().tasks.length} tasks completed</small></div>
      <div className="profile"><div className="avatar">RK</div><div><strong>Roadmap keeper</strong><small>Robotics + AI/ML</small></div><MoreHorizontal size={18} className="muted" /></div>
    </aside>
    <main className="main-column">
      <header className="topbar">
        <div className="mobile-brand"><span className="brand-mark"><WandSparkles size={17} /></span>ROUTE<span className="brand-muted">/24</span></div>
        <div className="breadcrumbs"><span>Workspace</span><span className="slash">/</span><b>{breadcrumb(location.pathname)}</b></div>
        <div className="top-actions"><button className="search-trigger" onClick={() => setSearchOpen(true)}><Search size={15} /><span>Search anything...</span><kbd><Command size={11} /> K</kbd></button><button className="icon-button theme-button" title="Toggle theme" onClick={() => useRoadmap.getState().setTheme(theme === 'dark' ? 'light' : 'dark')}>{theme === 'dark' ? <Sun size={17} /> : <Moon size={17} />}</button></div>
      </header>
      <div className="mobile-progress"><span>Plan progress</span><div className="progress-track"><i style={{ width: `${progress}%` }} /></div><b>{progress}%</b></div>
      <AnimatePresence mode="wait"><motion.div key={location.pathname} className="page-wrap" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -5 }} transition={{ duration: 0.18 }}><Routes>
        <Route path="/" element={<Dashboard />} />
        <Route path="/tracker" element={<Tracker />} />
        <Route path="/task/:id" element={<TaskDetail />} />
        <Route path="/weeks" element={<Weeks />} />
        <Route path="/weeks/:n" element={<WeekDetail />} />
        <Route path="/phases/:id" element={<PhasePage />} />
        <Route path="/tracks/:name" element={<TrackPage />} />
        <Route path="/projects" element={<Projects />} />
        <Route path="/projects/:slug" element={<ProjectDetail />} />
        <Route path="/reviews" element={<Reviews />} />
        <Route path="/analytics" element={<Analytics />} />
        <Route path="/resume" element={<Resume />} />
        <Route path="/settings" element={<SettingsPage />} />
        <Route path="*" element={<NotFound />} />
      </Routes></motion.div></AnimatePresence>
      <MobileNav />
    </main>
    {searchOpen && <div className="command-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) setSearchOpen(false) }}><section className="command-box"><div className="command-input"><Search size={18} /><input autoFocus value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search tasks, projects, pages..." /><kbd>ESC</kbd></div>{search.trim() ? <div className="command-results">{results.length ? results.map((task) => <Link key={task.id} to={`/task/${task.id}`} onClick={() => setSearchOpen(false)}><span className={`track-dot ${trackClass[task.track]}`} /><span>{task.topic}<small>{task.project} · W{String(task.week).padStart(2, '0')}</small></span><ArrowUpRight size={15} /></Link>) : <div className="empty-small">No tasks found for “{search}”.</div>}</div> : <div className="command-shortcuts"><span>Quick jump</span><Link to="/tracker" onClick={() => setSearchOpen(false)}>All tasks <kbd>T</kbd></Link><Link to="/weeks" onClick={() => setSearchOpen(false)}>Week planner <kbd>W</kbd></Link><Link to="/analytics" onClick={() => setSearchOpen(false)}>Analytics <kbd>A</kbd></Link></div>}</section></div>}
    {celebration && <div className="confetti-burst" aria-hidden="true">{Array.from({ length: 28 }, (_, index) => <i key={index} style={{ '--x': `${((index % 7) - 3) * 36}px`, '--y': `${70 + Math.floor(index / 7) * 38}px`, '--r': `${index * 53}deg` } as React.CSSProperties} />)}</div>}
    {toast && <div className="toast" role="status"><span><Check size={14} /> {toast.message}</span><button onClick={toast.undo}>Undo</button><button aria-label="Dismiss notification" onClick={() => setToast(null)}><X size={14} /></button></div>}
  </div>
}

function breadcrumb(path: string) { if (path === '/') return 'Overview'; const last = path.split('/').filter(Boolean).at(-1) ?? ''; return last.replace(/-/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase()) }
function MobileNav() { return <nav className="mobile-nav">{[{ to: '/', label: 'Home', icon: LayoutDashboard }, { to: '/tracker', label: 'Tasks', icon: ListTodo }, { to: '/weeks', label: 'Weeks', icon: Timer }, { to: '/analytics', label: 'Stats', icon: Activity }, { to: '/settings', label: 'Setup', icon: Settings }].map(({ to, label, icon: Icon }) => <NavLink end={to === '/'} to={to} key={to} className={({ isActive }) => isActive ? 'mobile-tab active' : 'mobile-tab'}><Icon size={18} /><small>{label}</small></NavLink>)}</nav> }
function PageTitle({ eyebrow, title, subtitle, action }: { eyebrow?: string; title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="page-title"><div>{eyebrow && <p className="eyebrow">{eyebrow}</p>}<h1>{title}</h1>{subtitle && <p className="subtitle">{subtitle}</p>}</div>{action && <div>{action}</div>}</div> }
function Panel({ title, meta, children, className = '' }: { title?: string; meta?: React.ReactNode; children: React.ReactNode; className?: string }) { return <section className={`panel ${className}`}>{(title || meta) && <div className="panel-heading">{title && <h2>{title}</h2>}{meta}</div>}{children}</section> }
function ProgressBar({ value, color = 'violet' }: { value: number; color?: string }) { return <div className={`progress-track ${color}`}><i style={{ width: `${value}%` }} /></div> }
function Ring({ value, size = 122, label }: { value: number; size?: number; label?: string }) { return <div className="ring" style={{ width: size, height: size, background: `conic-gradient(var(--lime) ${value * 3.6}deg, var(--line) 0deg)` }}><div className="ring-inner"><strong>{value}<small>%</small></strong>{label && <span>{label}</span>}</div></div> }
function StatusPill({ status, onChange }: { status: Status; onChange?: (status: Status) => void }) { const order: Status[] = ['Not started', 'In progress', 'Done']; return onChange ? <select className={`status-select status-${slugify(status)}`} value={status} onChange={(event) => onChange(event.target.value as Status)} aria-label="Task status">{order.map((item) => <option key={item}>{item}</option>)}</select> : <span className={`status-badge status-${slugify(status)}`}>{status}</span> }
function TaskRow({ task, compact = false }: { task: Task; compact?: boolean }) { const updateTask = useRoadmap((state) => state.updateTask); return <div className={`task-row${compact ? ' compact' : ''}`}><button className={`task-check ${task.status === 'Done' ? 'checked' : ''}`} aria-label={`Mark ${task.topic} ${task.status === 'Done' ? 'not done' : 'done'}`} onClick={() => updateTask(task.id, { status: task.status === 'Done' ? 'Not started' : 'Done', dateDone: task.status === 'Done' ? '' : new Date().toISOString().slice(0, 10) })}>{task.status === 'Done' && <Check size={13} />}</button><Link to={`/task/${task.id}`} className="task-main"><span className="task-title">{task.topic}</span><span className="task-subline"><span className={`track-dot ${trackClass[task.track]}`} />{task.track}<span className="dot-sep">·</span>{task.project}</span></Link><span className="task-week">W{String(task.week).padStart(2, '0')}</span>{!compact && <StatusPill status={task.status} onChange={(status) => updateTask(task.id, { status, dateDone: status === 'Done' ? task.dateDone || new Date().toISOString().slice(0, 10) : task.dateDone })} />}</div> }
function Dashboard() {
  const tasks = useRoadmap((state) => state.tasks)
  const reviews = useRoadmap((state) => state.reviews)
  const startDate = useRoadmap((state) => state.startDate)
  const pausedWeeks = useRoadmap((state) => state.pausedWeeks)
  const week = currentWeek(startDate, pausedWeeks)
  const done = tasks.filter((task) => task.status === 'Done').length
  const trend = Array.from({ length: 8 }, (_, index) => { const n = index + 1; return { week: `W${String(n).padStart(2, '0')}`, hours: reviews[n]?.hoursSpent ?? 0 } })
  const upcoming = tasks.filter((task) => task.status !== 'Done').sort((a, b) => a.week - b.week).slice(0, 4)
  const thisWeekTasks = tasks.filter((task) => task.week === week).slice(0, 3)
  const milestones = [...new Set(upcoming.map((task) => task.project))].slice(0, 4).map((project) => ({ project, task: upcoming.find((task) => task.project === project)!, items: tasks.filter((task) => task.project === project) }))
  const streak = Object.values(reviews).filter((review) => review.postedThisWeek).length
  return <><PageTitle eyebrow={`WEEK ${String(week).padStart(2, '0')} / 24 · ${phases[Math.min(4, Math.ceil(week / 4) - 1)]}`} title="Build your next chapter." subtitle="A clear view of the work that turns robotics + AI ambition into proof." action={<Link className="button primary" to={`/weeks/${week}`}>Open this week <ArrowRight size={16} /></Link>} />
    <div className="dashboard-grid"><section className="hero-panel panel"><div className="hero-copy"><span className="eyebrow">ROADMAP PROGRESS</span><h2>Small steps.<br /><em>Real momentum.</em></h2><p>{done === 0 ? 'Your first milestone is waiting. Pick one task and make it real.' : `${done} finished task${done === 1 ? '' : 's'} down. Keep the weekly rhythm moving.`}</p><Link to="/tracker" className="text-link">View all tasks <ArrowRight size={15} /></Link></div><div className="hero-ring"><Ring value={taskProgress(tasks)} /><span>{done} <i>/</i> {tasks.length} tasks</span></div><div className="hero-orbit orbit-one" /><div className="hero-orbit orbit-two" /></section>
      <Panel className="week-panel"><div className="week-stat"><div><span className="eyebrow">CURRENT WEEK</span><strong>{String(week).padStart(2, '0')}<small> / 24</small></strong></div><div className="week-icon"><Timer size={19} /></div></div><ProgressBar value={weekProgress(tasks, week)} /><div className="week-foot"><span>{weekProgress(tasks, week)}% complete</span><span className="streak-label"><Activity size={14} /> {streak} review streak</span></div><div className="quick-week-list">{thisWeekTasks.length ? thisWeekTasks.map((task) => <TaskRow task={task} compact key={task.id} />) : <span className="quick-empty">No tasks loaded for this week.</span>}</div><Link to={`/weeks/${week}`} className="panel-link">Plan this week <ArrowUpRight size={14} /></Link></Panel>
      <Panel className="track-panel" title="Track progress" meta={<Link to="/analytics" className="subtle-link">Details <ArrowRight size={13} /></Link>}><div className="track-list">{tracks.map((track) => { const items = tasks.filter((task) => task.track === track); return <Link to={`/tracks/${slugify(track)}`} className="track-progress-row" key={track}><span className={`track-icon ${trackClass[track]}`}>{track.slice(0, 1)}</span><span className="track-label">{track}</span><span className="track-count">{items.filter((task) => task.status === 'Done').length}/{items.length}</span><ProgressBar value={taskProgress(items)} color={trackClass[track]} /></Link> })}</div></Panel>
      <Panel title="Hours invested" className="hours-panel" meta={<span className="tag muted-tag">LAST 8 WEEKS</span>}><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend} margin={{ top: 8, right: 4, left: -22, bottom: 0 }}><defs><linearGradient id="hoursFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c7f36b" stopOpacity={0.28} /><stop offset="100%" stopColor="#c7f36b" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="4 5" /><XAxis dataKey="week" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 10 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 10 }} /><Tooltip contentStyle={{ background: 'var(--panel)', border: '1px solid var(--line)', borderRadius: 12, color: 'var(--ink)' }} /><Area type="monotone" dataKey="hours" stroke="#c7f36b" strokeWidth={2.5} fill="url(#hoursFill)" /></AreaChart></ResponsiveContainer></div></Panel>
      <Panel title="24-week map" className="heatmap-panel" meta={<Link className="subtle-link" to="/weeks">All weeks <ArrowRight size={13} /></Link>}><div className="heatmap">{Array.from({ length: 24 }, (_, index) => { const n = index + 1; const value = weekProgress(tasks, n); return <Link title={`${prettyWeek(n)} · ${value}% complete`} key={n} to={`/weeks/${n}`} className={`heat-cell heat-${value === 100 ? 'done' : value ? 'active' : 'empty'}${n === week ? ' current' : ''}`}><span>{String(n).padStart(2, '0')}</span><i style={{ '--heat': `${value}%` } as React.CSSProperties} /></Link> })}</div><div className="heat-legend"><span><i className="heat-empty" /> Not started</span><span><i className="heat-active" /> In progress</span><span><i className="heat-done" /> Complete</span></div></Panel>
      <Panel title="Upcoming milestones" className="upnext-panel" meta={<Link className="subtle-link" to="/projects">All projects <ArrowRight size={13} /></Link>}>{milestones.length ? milestones.map(({ project, task, items }) => <Link className="milestone-row" key={project} to={`/projects/${slugify(project)}`}><span className="milestone-bullet"><Target size={14} /></span><span className="milestone-copy"><strong>{project}</strong><small>Next · W{String(task.week).padStart(2, '0')} · {task.topic}</small><ProgressBar value={taskProgress(items)} /></span><span className="milestone-percent">{taskProgress(items)}%</span></Link>) : <EmptyState title="All milestones complete" text="Your project list is clear." />}</Panel>
    </div>
  </>
}

function Tracker() {
  const tasks = useRoadmap((state) => state.tasks)
  const updateMany = useRoadmap((state) => state.updateMany)
  const [params, setParams] = useSearchParams()
  const [view, setView] = useState<'list' | 'kanban' | 'table'>('list')
  const [selected, setSelected] = useState<string[]>([])
  const [query, setQuery] = useState(params.get('q') ?? '')
  const track = params.get('track') ?? ''
  const phase = params.get('phase') ?? ''
  const week = params.get('week') ?? ''
  const status = params.get('status') ?? ''
  const project = params.get('project') ?? ''
  const filtered = tasks.filter((task) => (!query || `${task.id} ${task.topic} ${task.project}`.toLowerCase().includes(query.toLowerCase())) && (!track || task.track === track) && (!phase || task.phase === Number(phase)) && (!week || task.week === Number(week)) && (!status || task.status === status) && (!project || task.project === project))
  const put = (key: string, value: string) => { const next = new URLSearchParams(params); value ? next.set(key, value) : next.delete(key); setParams(next) }
  const grouped = Object.fromEntries((['Not started', 'In progress', 'Done'] as Status[]).map((item) => [item, filtered.filter((task) => task.status === item)])) as Record<Status, Task[]>
  return <><PageTitle eyebrow="YOUR WORK, IN MOTION" title="Task tracker" subtitle={`${filtered.length} tasks · update status, add a note, keep the plan yours.`} action={<button className="button secondary" onClick={() => { const blob = new Blob([JSON.stringify(tasks, null, 2)], { type: 'application/json' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'roadmap-tasks.json'; link.click(); URL.revokeObjectURL(link.href) }}><Download size={15} /> Export</button>} />
    <section className="panel filter-panel"><div className="tracker-search"><Search size={16} /><input value={query} onChange={(event) => { setQuery(event.target.value); put('q', event.target.value) }} placeholder="Search tasks, projects, IDs..." /></div><select value={track} onChange={(event) => put('track', event.target.value)}><option value="">All tracks</option>{tracks.map((item) => <option key={item}>{item}</option>)}</select><select value={phase} onChange={(event) => put('phase', event.target.value)}><option value="">All phases</option>{phases.map((item, index) => <option value={index + 1} key={item}>Phase {index + 1} · {item}</option>)}</select><select value={week} onChange={(event) => put('week', event.target.value)}><option value="">All weeks</option>{Array.from({ length: 24 }, (_, index) => <option key={index + 1} value={index + 1}>{prettyWeek(index + 1)}</option>)}</select><select value={project} onChange={(event) => put('project', event.target.value)}><option value="">All projects</option>{projects.map((item) => <option key={item}>{item}</option>)}</select><select value={status} onChange={(event) => put('status', event.target.value)}><option value="">All status</option>{['Not started', 'In progress', 'Done'].map((item) => <option key={item}>{item}</option>)}</select><div className="view-switch">{([{ id: 'list', icon: ListTodo }, { id: 'kanban', icon: FolderKanban }, { id: 'table', icon: Table2 }] as const).map(({ id, icon: Icon }) => <button className={view === id ? 'selected' : ''} onClick={() => setView(id)} key={id} aria-label={`${id} view`}><Icon size={16} /></button>)}</div></section>
    {selected.length > 0 && <div className="bulk-bar"><span>{selected.length} selected</span><select id="bulk-status"><option>Not started</option><option>In progress</option><option>Done</option></select><button className="button primary small" onClick={() => { updateMany(selected, (document.querySelector('#bulk-status') as HTMLSelectElement).value as Status); setSelected([]) }}>Apply status</button><button className="icon-button" onClick={() => setSelected([])}><X size={15} /></button></div>}
    {view === 'list' ? <div className="panel task-list-panel">{filtered.length ? filtered.map((task) => <div className="selectable-task" key={task.id}><input type="checkbox" checked={selected.includes(task.id)} onChange={(event) => setSelected(event.target.checked ? [...selected, task.id] : selected.filter((id) => id !== task.id))} aria-label={`Select ${task.id}`} /><TaskRow task={task} /></div>) : <EmptyState title="No tasks match" text="Try removing one of the filters." />}</div> : view === 'table' ? <div className="panel table-scroll"><table className="task-table"><thead><tr><th></th><th>ID</th><th>Task</th><th>Track</th><th>Project</th><th>Week</th><th>Status</th></tr></thead><tbody>{filtered.map((task) => <tr key={task.id}><td><input type="checkbox" checked={selected.includes(task.id)} onChange={(event) => setSelected(event.target.checked ? [...selected, task.id] : selected.filter((id) => id !== task.id))} /></td><td className="mono">{task.id}</td><td><Link to={`/task/${task.id}`}>{task.topic}</Link></td><td>{task.track}</td><td>{task.project}</td><td>W{String(task.week).padStart(2, '0')}</td><td><StatusPill status={task.status} /></td></tr>)}</tbody></table></div> : <DndContext onDragEnd={(event: DragEndEvent) => { const id = String(event.active.id); const nextStatus = String(event.over?.id ?? '') as Status; if (['Not started', 'In progress', 'Done'].includes(nextStatus)) updateMany([id], nextStatus) }}><div className="kanban-grid">{(['Not started', 'In progress', 'Done'] as Status[]).map((column) => <KanbanColumn key={column} status={column} tasks={grouped[column]} />)}</div></DndContext>}
  </>
}
function KanbanColumn({ status, tasks }: { status: Status; tasks: Task[] }) { const { setNodeRef, isOver } = useDroppable({ id: status }); return <div ref={setNodeRef} className={`kanban-column ${isOver ? 'drag-over' : ''}`}><div className="kanban-heading"><span className={`status-dot ${slugify(status)}`} />{status}<b>{tasks.length}</b></div>{tasks.map((task) => <DraggableTask task={task} key={task.id} />)}</div> }
function DraggableTask({ task }: { task: Task }) { const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({ id: task.id }); return <Link ref={setNodeRef} to={`/task/${task.id}`} className={`kanban-card${isDragging ? ' dragging' : ''}`} style={transform ? { transform: `translate3d(${transform.x}px,${transform.y}px,0)` } : undefined} {...listeners} {...attributes}><span className="mono">{task.id}</span><strong>{task.topic}</strong><span className="task-subline"><span className={`track-dot ${trackClass[task.track]}`} />{task.track} · W{task.week}</span></Link> }
function TaskDetail() { const { id = '' } = useParams(); const task = useRoadmap((state) => state.tasks.find((item) => item.id === id)); const updateTask = useRoadmap((state) => state.updateTask); const tasks = useRoadmap((state) => state.tasks); const index = tasks.findIndex((item) => item.id === id); if (!task) return <NotFound />; const done = task.status === 'Done'; return <><Link to="/tracker" className="back-link"><ArrowLeft size={15} /> All tasks</Link><PageTitle eyebrow={`${prettyWeek(task.week)} · PHASE ${task.phase}`} title={task.topic} subtitle={`${task.id} · ${task.project}`} action={<StatusPill status={task.status} onChange={(status) => updateTask(task.id, { status, dateDone: status === 'Done' ? task.dateDone || new Date().toISOString().slice(0, 10) : task.dateDone })} />} /><div className="detail-grid"><div className="detail-main"><Panel title="Done when"><p className="output-text">{task.output}</p></Panel><Panel title="Working notes" meta={<span className="saved-label"><span className="live-dot" /> Auto-saved</span>}><textarea className="notes-area" value={task.notes} onChange={(event) => updateTask(task.id, { notes: event.target.value })} placeholder="Capture an idea, blocker, or useful detail..." /></Panel><Panel title="Task navigation"><div className="task-navigation">{tasks[index - 1] ? <Link to={`/task/${tasks[index - 1].id}`}><ArrowLeft size={15} /><span><small>PREVIOUS</small>{tasks[index - 1].topic}</span></Link> : <span />}{tasks[index + 1] ? <Link className="next-task" to={`/task/${tasks[index + 1].id}`}><span><small>NEXT</small>{tasks[index + 1].topic}</span><ArrowRight size={15} /></Link> : <span />}</div></Panel></div><aside className="detail-aside"><Panel title="Task status"><StatusPill status={task.status} onChange={(status) => updateTask(task.id, { status, dateDone: status === 'Done' ? task.dateDone || new Date().toISOString().slice(0, 10) : task.dateDone })} /><label className="field-label">Date completed</label><input type="date" value={task.dateDone} onChange={(event) => updateTask(task.id, { dateDone: event.target.value, status: event.target.value ? 'Done' : task.status })} /><button className={`button ${done ? 'secondary' : 'primary'} full-button`} onClick={() => updateTask(task.id, { status: done ? 'Not started' : 'Done', dateDone: done ? '' : new Date().toISOString().slice(0, 10) })}>{done ? <CheckCheck size={15} /> : <Check size={15} />}{done ? 'Completed' : 'Mark as done'}</button></Panel><Panel title="Plan details"><DetailField label="Track" value={<Link to={`/tracks/${slugify(task.track)}`}><span className={`track-dot ${trackClass[task.track]}`} /> {task.track}</Link>} /><DetailField label="Project" value={<Link to={`/projects/${slugify(task.project)}`}>{task.project}</Link>} /><DetailField label="Week" value={<Link to={`/weeks/${task.week}`}>{prettyWeek(task.week)} <ArrowUpRight size={12} /></Link>} /><DetailField label="Phase" value={<Link to={`/phases/${task.phase}`}>Phase {task.phase}: {phases[task.phase - 1]}</Link>} /></Panel>{task.resource && <Panel title="Resource"><a className="resource-link" href={task.resource} target="_blank" rel="noreferrer">Open reference <ExternalLink size={14} /></a></Panel>}</aside></div></> }
function DetailField({ label, value }: { label: string; value: React.ReactNode }) { return <div className="detail-field"><span>{label}</span><strong>{value}</strong></div> }
function Weeks() { const tasks = useRoadmap((state) => state.tasks); const start = useRoadmap((state) => state.startDate); const paused = useRoadmap((state) => state.pausedWeeks); const current = currentWeek(start, paused); return <><PageTitle eyebrow="PLAN IN SPRINTS" title="Week planner" subtitle="Twenty-four focused chapters. One deliberate step at a time." /><div className="phase-strip">{phases.map((phase, index) => <Link to={`/phases/${index + 1}`} key={phase}><span>0{index + 1}</span><strong>{phase}</strong><small>Weeks {phaseRange(index + 1).join('–')}</small></Link>)}</div><div className="weeks-grid">{Array.from({ length: 24 }, (_, index) => { const n = index + 1; const count = tasks.filter((task) => task.week === n).length; const value = weekProgress(tasks, n); return <Link className={`week-card${n === current ? ' current' : ''}`} to={`/weeks/${n}`} key={n}><div className="week-card-top"><span>{prettyWeek(n)}</span><Ring size={46} value={value} /></div><h2>{phases[Math.min(4, Math.ceil(n / 4) - 1)]}</h2><ProgressBar value={value} /><div className="week-card-bottom"><span>{count} planned tasks</span><span>{value}% <ArrowUpRight size={13} /></span></div></Link> })}</div></> }
function WeekDetail() { const { n = '1' } = useParams(); const week = Math.max(1, Math.min(24, Number(n))); const tasks = useRoadmap((state) => state.tasks); const reviews = useRoadmap((state) => state.reviews); const saveReview = useRoadmap((state) => state.saveReview); const review = getReview(reviews, week); const thisWeekTasks = tasks.filter((task) => task.week === week); const nextTasks = tasks.filter((task) => task.week === week + 1 && task.status !== 'Done'); const groups = tracks.map((track) => ({ track, tasks: thisWeekTasks.filter((task) => task.track === track) })).filter((group) => group.tasks.length); return <><Link to="/weeks" className="back-link"><ArrowLeft size={15} /> All weeks</Link><PageTitle eyebrow={`PHASE ${Math.min(5, Math.ceil(week / 4))} · ${phases[Math.min(4, Math.ceil(week / 4) - 1)].toUpperCase()}`} title={prettyWeek(week)} subtitle="Make space for the work, then capture what you learned." action={<div className="page-stepper">{week > 1 && <Link to={`/weeks/${week - 1}`}><ArrowLeft size={15} /></Link>}{week < 24 && <Link to={`/weeks/${week + 1}`}><ArrowRight size={15} /></Link>}</div>} /><div className="week-summary"><Ring size={82} value={weekProgress(tasks, week)} /><div><span className="eyebrow">WEEKLY PROGRESS</span><strong>{thisWeekTasks.filter((task) => task.status === 'Done').length} of {thisWeekTasks.length} tasks complete</strong><p>{weekProgress(tasks, week) === 100 ? 'Week complete. Take a moment to mark the win.' : 'Keep your focus on the next useful deliverable.'}</p></div></div><div className="week-detail-grid"><div>{groups.length ? groups.map(({ track, tasks: groupTasks }) => <Panel title={track} key={track} className="week-task-panel">{groupTasks.map((task) => <TaskRow task={task} key={task.id} />)}</Panel>) : <Panel><EmptyState title="No tasks scheduled" text="Your imported plan has no tasks for this week yet." /></Panel>}</div><WeeklyReviewForm review={review} onChange={(next) => saveReview(week, next)} nextTasks={nextTasks} /></div></> }
function WeeklyReviewForm({ review, onChange, nextTasks }: { review: Review; onChange: (review: Review) => void; nextTasks: Task[] }) { const [prefilled, setPrefilled] = useState(false); return <Panel title="Weekly review" meta={<span className="tag muted-tag">AUTO-SAVED</span>} className="review-form"><label className="field-label">Hours invested<input type="number" min="0" step="0.5" value={review.hoursSpent} onChange={(event) => onChange({ ...review, hoursSpent: Number(event.target.value) })} /></label><label className="field-label">What did I finish?<textarea value={review.whatIFinished} onChange={(event) => onChange({ ...review, whatIFinished: event.target.value })} placeholder="The thing I am proud of..." /></label><label className="field-label">What blocked me?<textarea value={review.whatBlockedMe} onChange={(event) => onChange({ ...review, whatBlockedMe: event.target.value })} placeholder="Name the friction; make it actionable." /></label><label className="review-check"><input type="checkbox" checked={review.postedThisWeek} onChange={(event) => onChange({ ...review, postedThisWeek: event.target.checked })} /> I shared a progress update this week</label><label className="field-label">Next week's goals<textarea value={review.nextWeeksGoals} onChange={(event) => onChange({ ...review, nextWeeksGoals: event.target.value })} placeholder="Set a small, specific intention..." /></label><button className="button secondary small" onClick={() => { onChange({ ...review, nextWeeksGoals: nextTasks.map((task) => `- ${task.topic}`).join('\n') }); setPrefilled(true) }}><WandSparkles size={14} /> Prefill from unfinished tasks</button>{prefilled && <span className="inline-confirm">Goals drafted from next week's plan.</span>}</Panel> }
function PhasePage() { const { id = '' } = useParams(); const phase = Number(id); const tasks = useRoadmap((state) => state.tasks); const [from, to] = phaseRange(phase); if (!phases[phase - 1]) return <NotFound />; const items = tasks.filter((task) => task.phase === phase); return <><PageTitle eyebrow={`PHASE ${String(phase).padStart(2, '0')} · WEEKS ${from}–${to}`} title={phases[phase - 1]} subtitle={['Build the basics and create a steady rhythm.', 'Turn fundamentals into working prototypes.', 'Go deep on a research-grade flagship.', 'Make useful models real, accessible products.', 'Polish, publish, and make your work legible.'][phase - 1]} action={<Ring size={74} value={taskProgress(items)} />} /><div className="phase-timeline">{Array.from({ length: to - from + 1 }, (_, index) => { const week = from + index; return <section key={week}><Link className="timeline-week" to={`/weeks/${week}`}><span>{prettyWeek(week)}</span><strong>{weekProgress(tasks, week)}%</strong><ProgressBar value={weekProgress(tasks, week)} /><ArrowUpRight size={14} /></Link><div>{tasks.filter((task) => task.week === week).map((task) => <TaskRow task={task} key={task.id} compact />)}</div></section> })}</div></> }
function TrackPage() { const { name = '' } = useParams(); const track = tracks.find((item) => slugify(item) === name || item.toLowerCase() === decodeURIComponent(name).toLowerCase()); const tasks = useRoadmap((state) => state.tasks); if (!track) return <NotFound />; const items = tasks.filter((task) => task.track === track); const weeks = [...new Set(items.map((task) => task.week))].sort((a, b) => a - b); return <><div className={`track-hero panel ${trackClass[track]}`}><span className="eyebrow">TRACK / 0{tracks.indexOf(track) + 1}</span><h1>{track}</h1><p>{trackSummary[track]}</p><div className="track-hero-bottom"><Ring value={taskProgress(items)} size={68} /><span>{items.filter((task) => task.status === 'Done').length} / {items.length} tasks complete</span></div></div><PageTitle title="Timeline" subtitle="Follow this thread across your 24-week roadmap." /><div className="phase-timeline">{weeks.length ? weeks.map((week) => <section key={week}><Link className="timeline-week" to={`/weeks/${week}`}><span>{prettyWeek(week)}</span><strong>{weekProgress(tasks, week)}%</strong><ProgressBar value={weekProgress(tasks, week)} /><ArrowUpRight size={14} /></Link><div>{items.filter((task) => task.week === week).map((task) => <TaskRow task={task} key={task.id} compact />)}</div></section>) : <Panel><EmptyState title="No track tasks yet" text="Add this track's plan rows to data/tasks.json." /></Panel>}</div></> }
const trackSummary: Record<Track, string> = { 'AI/ML': 'Build sound machine learning foundations, then ship models that solve real problems.', Robotics: 'Make intelligent machines move, perceive, and interact with the world.', 'Design/Web': 'Turn your technical work into clear, accessible experiences people can use.', 'Video/Social': 'Show the process behind your projects and build a visible trail of progress.', Resume: 'Translate your work into a portfolio and story that opens the next door.' }
function Projects() { const tasks = useRoadmap((state) => state.tasks); return <><PageTitle eyebrow="FLAGSHIPS & SHIPABLES" title="Project library" subtitle="A portfolio of proof, built one milestone at a time." /><div className="projects-grid">{projects.map((project, index) => { const items = tasks.filter((task) => task.project === project); const range = items.length ? `${Math.min(...items.map((task) => task.week))}–${Math.max(...items.map((task) => task.week))}` : '—'; return <Link to={`/projects/${slugify(project)}`} className={`project-card panel project-${index % 4}`} key={project}><div className="project-card-top"><span className="project-index">{String(index + 1).padStart(2, '0')} / PROJECT</span><ArrowUpRight size={16} /></div><span className="project-sigil">{project.split(' ')[0]}</span><h2>{project.replace(/^(R\d|H\d) /, '')}</h2><p>{projectDescription[project]}</p><div className="project-card-bottom"><span>Weeks {range}</span><span>{taskProgress(items)}% complete</span></div><ProgressBar value={taskProgress(items)} /></Link> })}</div></> }
const projectDescription: Record<string, string> = { 'R1 Service robot': 'A helpful mobile robot built around robust perception and navigation.', 'R2 Warehouse robot': 'A logistics prototype for efficient and safe warehouse movement.', 'R3 Medical arm': 'A precision manipulation concept grounded in human-centered design.', 'R4 Humanoid RL': 'A simulated humanoid learning to move through reinforcement learning.', 'H2 Thermal CNN-Transformer': 'A hybrid architecture for learning from thermal imagery.', 'H4 RAG + LoRA': 'A compact, grounded language model application with retrieval.', 'H5 Paper reproduction': 'A careful reproduction that makes a research result trustworthy.', 'Portfolio site': 'A thoughtful home for experiments, engineering, and evidence.' }
function ProjectDetail() { const { slug = '' } = useParams(); const project = projects.find((item) => slugify(item) === slug); const tasks = useRoadmap((state) => state.tasks); const projectLinks = useRoadmap((state) => state.projectLinks); const setProjectLinks = useRoadmap((state) => state.setProjectLinks); if (!project) return <NotFound />; const items = tasks.filter((task) => task.project === project); const links = projectLinks[project] ?? { github: '', demo: '', live: '' }; const weeks = [...new Set(items.map((task) => task.week))].sort((a, b) => a - b); return <><Link to="/projects" className="back-link"><ArrowLeft size={15} /> Projects</Link><PageTitle eyebrow="PROJECT / MILESTONE PLAN" title={project} subtitle={projectDescription[project]} action={<Ring size={76} value={taskProgress(items)} />} /><div className="project-detail-grid"><div><Panel title="Task checklist">{items.length ? items.map((task) => <TaskRow task={task} key={task.id} />) : <EmptyState title="No milestones loaded yet" text="Add project tasks to data/tasks.json to build this checklist." />}</Panel><Panel title="Milestone timeline"><div className="milestones">{weeks.length ? weeks.map((week) => <Link to={`/weeks/${week}`} key={week}><span className="milestone-marker" /><span><small>{prettyWeek(week)}</small><strong>{items.filter((task) => task.week === week).map((task) => task.topic).join(' · ')}</strong></span><ArrowUpRight size={14} /></Link>) : <EmptyState title="Timeline will appear here" text="Milestones are grouped by their planned week." />}</div></Panel></div><Panel title="Project links" className="project-links-panel"><p className="muted">Keep the shipped work one click away.</p>{([['github', 'GitHub repository'], ['demo', 'Demo video'], ['live', 'Live project']] as const).map(([key, label]) => <label className="field-label" key={key}>{label}<input type="url" placeholder="https://" value={links[key]} onChange={(event) => setProjectLinks(project, { ...links, [key]: event.target.value })} /></label>)}</Panel></div></> }
function Reviews() { const reviews = useRoadmap((state) => state.reviews); const tasks = useRoadmap((state) => state.tasks); const rows = Array.from({ length: 24 }, (_, index) => ({ week: index + 1, ...(reviews[index + 1] ?? getReview(reviews, index + 1)) })).filter((review) => review.hoursSpent || review.whatIFinished || review.whatBlockedMe || review.postedThisWeek || review.nextWeeksGoals); const chart = Array.from({ length: 24 }, (_, index) => ({ week: `W${String(index + 1).padStart(2, '0')}`, hours: reviews[index + 1]?.hoursSpent ?? 0 })); const posting = rows.filter((review) => review.postedThisWeek).length; return <><PageTitle eyebrow="LOOK BACK, MOVE FORWARD" title="Weekly reviews" subtitle="A record of the work, friction, and ideas worth carrying ahead." action={<Link className="button secondary" to="/weeks">Open week planner <ArrowRight size={15} /></Link>} /><div className="stats-row"><Metric label="Hours logged" value={Object.values(reviews).reduce((sum, item) => sum + item.hoursSpent, 0)} suffix="h" /><Metric label="Reviews captured" value={rows.length} /><Metric label="Progress posts" value={posting} /><Metric label="Posted streak" value={posting ? Math.min(posting, 4) : 0} suffix=" wk" /></div><Panel title="Hours over time" className="wide-chart"><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={chart}><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="4 5" /><XAxis dataKey="week" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 10 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 10 }} /><Tooltip contentStyle={{ background: 'var(--panel)', border: '1px solid var(--line)', borderRadius: 12, color: 'var(--ink)' }} /><Bar dataKey="hours" fill="#c7f36b" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer></div></Panel><div className="review-timeline"><h2>Review timeline</h2>{rows.length ? rows.sort((a, b) => b.week - a.week).map((review) => <article className="review-entry panel" key={review.week}><Link to={`/weeks/${review.week}`} className="review-week">{prettyWeek(review.week)} <ArrowUpRight size={13} /></Link><span className="review-hours"><Timer size={14} /> {review.hoursSpent}h</span>{review.whatIFinished && <p><strong>Finished</strong>{review.whatIFinished}</p>}{review.whatBlockedMe && <p><strong>Blocked by</strong>{review.whatBlockedMe}</p>}{review.postedThisWeek && <span className="tag green-tag">POSTED THIS WEEK</span>}</article>) : <Panel><EmptyState title="Your first review starts here" text="Write a weekly reflection from any week page. It will show up here." /></Panel>}</div><Panel title="Plan completion" className="review-task-foot"><ProgressBar value={taskProgress(tasks)} /><span>{taskProgress(tasks)}% complete across all weeks</span></Panel></> }
function Metric({ label, value, suffix = '' }: { label: string; value: number; suffix?: string }) { return <div className="metric panel"><span>{label}</span><strong>{value}{suffix}</strong></div> }
function Analytics() { const tasks = useRoadmap((state) => state.tasks); const reviews = useRoadmap((state) => state.reviews); const completed = tasks.filter((task) => task.status === 'Done'); const byWeek = Array.from({ length: 24 }, (_, index) => { const week = index + 1; return { week: `W${String(week).padStart(2, '0')}`, done: completed.filter((task) => task.week <= week).length, velocity: completed.filter((task) => task.week === week).length } }); const avgVelocity = completed.length ? completed.length / Math.max(1, Math.max(...completed.map((task) => task.week))) : 0; const forecastWeeks = avgVelocity ? Math.ceil((tasks.length - completed.length) / avgVelocity) : 24; const byTrack = tracks.map((track) => ({ track, done: completed.filter((task) => task.track === track).length })); const current = currentWeek(useRoadmap.getState().startDate, useRoadmap.getState().pausedWeeks); const planExpected = Math.round(tasks.length * current / 24); const isAhead = completed.length >= planExpected; return <><PageTitle eyebrow="MEASURE WHAT MATTERS" title="Analytics" subtitle="Use the signal to choose the next meaningful move." /><div className="stats-row"><Metric label="Completion" value={taskProgress(tasks)} suffix="%" /><Metric label="Weekly velocity" value={Number(avgVelocity.toFixed(1))} suffix=" / wk" /><Metric label="Hours invested" value={Object.values(reviews).reduce((sum, item) => sum + item.hoursSpent, 0)} suffix="h" /><div className={`metric panel schedule-metric ${isAhead ? 'ahead' : 'behind'}`}><span>Plan pace</span><strong>{isAhead ? 'Ahead' : 'Behind'}</strong><small>{completed.length} done · {planExpected} expected by now</small></div></div><div className="analytics-grid"><Panel title="Completion over time" className="analytics-chart"><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><AreaChart data={byWeek}><defs><linearGradient id="completionFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c7f36b" stopOpacity={0.25} /><stop offset="100%" stopColor="#c7f36b" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="4 5" /><XAxis dataKey="week" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 9 }} interval={2} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 10 }} /><Tooltip contentStyle={{ background: 'var(--panel)', border: '1px solid var(--line)', borderRadius: 12, color: 'var(--ink)' }} /><Area type="monotone" dataKey="done" stroke="#c7f36b" strokeWidth={2.5} fill="url(#completionFill)" /></AreaChart></ResponsiveContainer></div></Panel><Panel title="Tasks by track" className="track-chart"><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={byTrack} layout="vertical" margin={{ left: 12 }}><CartesianGrid horizontal={false} stroke="var(--line)" strokeDasharray="4 5" /><XAxis type="number" hide /><YAxis type="category" dataKey="track" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 10 }} width={78} /><Tooltip contentStyle={{ background: 'var(--panel)', border: '1px solid var(--line)', borderRadius: 12, color: 'var(--ink)' }} /><Bar dataKey="done" fill="#c7f36b" radius={[0, 4, 4, 0]} /></BarChart></ResponsiveContainer></div></Panel><Panel title="Weekly velocity" className="velocity-chart"><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={byWeek}><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="4 5" /><XAxis dataKey="week" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 9 }} interval={2} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 10 }} /><Tooltip contentStyle={{ background: 'var(--panel)', border: '1px solid var(--line)', borderRadius: 12, color: 'var(--ink)' }} /><Bar dataKey="velocity" fill="#a9b2c0" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer></div></Panel><Panel title="Finish forecast" className="forecast-panel"><div className="forecast-icon"><Gauge size={20} /></div><span className="eyebrow">AT CURRENT PACE</span><strong>{avgVelocity ? `${forecastWeeks} weeks` : 'Not enough data'}</strong><p>{avgVelocity ? `Based on ${avgVelocity.toFixed(1)} completed tasks per active week. Your original plan ends at week 24.` : 'Mark a few tasks done to unlock a useful forecast.'}</p></Panel></div></> }
function Resume() { const tasks = useRoadmap((state) => state.tasks.filter((task) => task.track === 'Resume')); const [checks, setChecks] = useState<Record<string, boolean>>(() => { try { return JSON.parse(localStorage.getItem('roadmap-resume-checks') ?? '{}') } catch { return {} } }); const setCheck = (id: string, value: boolean) => { const next = { ...checks, [id]: value }; setChecks(next); localStorage.setItem('roadmap-resume-checks', JSON.stringify(next)) }; const items = ['LinkedIn headline and about section refreshed', 'GitHub profile README and pinned repositories curated', 'Portfolio project links tested on mobile and desktop', 'Resume PDF updated with measurable project outcomes']; return <><PageTitle eyebrow="MAKE YOUR WORK LEGIBLE" title="Resume & portfolio" subtitle="The launch checklist for turning your roadmap into a clear professional story." /><Panel title="Resume track tasks" className="resume-task-panel">{tasks.length ? tasks.map((task) => <TaskRow task={task} key={task.id} />) : <EmptyState title="No resume tasks loaded" text="Resume track tasks from data/tasks.json will appear here." />}</Panel><Panel title="Portfolio checklist" meta={<span className="tag muted-tag">{Object.values(checks).filter(Boolean).length} / {items.length} READY</span>} className="portfolio-checklist">{items.map((item, index) => <label className="checklist-item" key={item}><input type="checkbox" checked={checks[String(index)] ?? false} onChange={(event) => setCheck(String(index), event.target.checked)} /><span><Check size={13} /></span>{item}</label>)}</Panel><div className="resume-links"><a href="https://www.linkedin.com" target="_blank" rel="noreferrer"><span className="link-mark linkedin">in</span>LinkedIn<ArrowUpRight size={14} /></a><a href="https://github.com" target="_blank" rel="noreferrer"><Github size={17} /> GitHub <ArrowUpRight size={14} /></a><Link to="/projects"><span className="link-mark portfolio-mark">↗</span>Project library <ArrowUpRight size={14} /></Link></div></> }
function SettingsPage() { const theme = useRoadmap((state) => state.theme); const startDate = useRoadmap((state) => state.startDate); const paused = useRoadmap((state) => state.pausedWeeks); const state = useRoadmap(); const [message, setMessage] = useState(''); const exportData = () => { const blob = new Blob([JSON.stringify({ tasks: state.tasks, reviews: state.reviews, theme, startDate, pausedWeeks: paused, projectLinks: state.projectLinks }, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'roadmap-tracker-backup.json'; link.click(); URL.revokeObjectURL(url) }; const importFile = async (file?: File) => { if (!file) return; try { const parsed = JSON.parse(await file.text()); if (!Array.isArray(parsed.tasks) || !parsed.tasks.every((task: Partial<Task>) => task.id && task.week && task.track && task.status)) throw new Error('That file does not look like a roadmap backup.'); state.importData(parsed); setMessage('Backup imported successfully.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not read that backup.') } }; const exportCsv = () => { const fields = ['id', 'phase', 'week', 'track', 'project', 'topic', 'output', 'resource', 'status', 'dateDone', 'notes']; const csv = [fields.join(','), ...state.tasks.map((task) => fields.map((field) => `"${String(task[field as keyof Task] ?? '').replaceAll('"', '""')}"`).join(','))].join('\n'); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' })); link.download = 'roadmap-tasks.csv'; link.click(); URL.revokeObjectURL(link.href) }; return <><PageTitle eyebrow="MAKE THE PLAN YOURS" title="Settings" subtitle="Adjust your timeline and keep your data portable." /><div className="settings-grid"><Panel title="Appearance"><div className="setting-row"><div><strong>Color theme</strong><small>Choose the contrast that feels right.</small></div><button className="theme-toggle" onClick={() => useRoadmap.getState().setTheme(theme === 'dark' ? 'light' : 'dark')}>{theme === 'dark' ? <><Moon size={15} /> Dark</> : <><Sun size={15} /> Light</>}<ChevronDown size={13} /></button></div></Panel><Panel title="Plan timeline"><label className="field-label">Plan start date<input type="date" value={startDate} onChange={(event) => state.setStartDate(event.target.value)} /></label><p className="setting-hint">Current week is calculated from this date.</p><label className="field-label">Pause / shift by exam weeks<input type="number" min="0" max="24" value={paused} onChange={(event) => state.setPausedWeeks(Math.max(0, Number(event.target.value)))} /></label><p className="setting-hint">Each paused week moves the current-week indicator later without changing task dates.</p></Panel><Panel title="Data portability"><p className="muted">Your plan and updates are stored locally in this browser. Keep a backup before switching devices.</p><div className="settings-actions"><button className="button secondary" onClick={exportData}><ArrowDownToLine size={15} /> Export JSON</button><button className="button secondary" onClick={exportCsv}><Table2 size={15} /> Export CSV</button><label className="button secondary file-button"><Download size={15} /> Import JSON<input type="file" accept="application/json,.json" onChange={(event) => importFile(event.target.files?.[0])} /></label></div>{message && <p className="inline-confirm">{message}</p>}</Panel><Panel title="Reset progress" className="danger-panel"><p className="muted">This removes all task updates, reviews, and project links from this browser. Export a backup first.</p><button className="button danger" onClick={() => { if (window.confirm('Reset all roadmap data stored in this browser?')) { state.reset(); localStorage.removeItem('roadmap-resume-checks'); setMessage('Roadmap reset to its original task plan.') } }}>Reset all data</button></Panel><Panel title="Plan data"><div className="data-summary"><span>Loaded task rows</span><strong>{state.tasks.length}</strong></div><p className="setting-hint">Replace <code>data/tasks.json</code> with your full plan. User updates are kept separately in the browser store.</p></Panel></div></> }
function EmptyState({ title, text }: { title: string; text: string }) { return <div className="empty-state"><div className="empty-icon"><CircleHelp size={19} /></div><strong>{title}</strong><span>{text}</span></div> }
function NotFound() { return <div className="not-found"><span className="eyebrow">404 / OFF THE MAP</span><h1>This route isn't in the plan.</h1><p>The page may have moved, or this item has not been added yet.</p><Link className="button primary" to="/">Back to overview <ArrowLeft size={15} /></Link></div> }

export default App